import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Booking_com.Search_locations import Search_locations
from Tools.Booking_com.Search_hotels import Search_hotels
from Tools.Booking_com.Get_Policies_of_the_hotel import Get_Policies_of_the_hotel

import traceback

# ===== MODULE-LEVEL CONSTANTS =====
LOCATION_NAME = "Ditmars Steinway"
CHECKIN_DATE = "2026-07-01"          # future date (now is 2026-06-01)
CHECKOUT_DATE = "2026-07-05"
ORDER_BY = "popularity"               # valid sort id from schema
ROOM_NUMBER = 1
FILTER_BY_CURRENCY = "USD"


def search_location(location_name: str):
    """
    Search for the location using Booking.com locations API.
    Returns (dest_id, dest_type) or (None, None) if not found.
    """
    try:
        results = Search_locations(location_name)
    except Exception:
        return (None, None)

    if not results or not isinstance(results, list):
        return (None, None)

    # Lenient match: first result whose name contains both parts of the query
    query_lower = location_name.lower()
    for entry in results:
        name = entry.get("name", "")
        if name and query_lower in name.lower():
            dest_id = entry.get("dest_id")
            dest_type = entry.get("dest_type")
            if dest_id and dest_type:
                return (dest_id, dest_type)

    # Fallback: return first result with valid dest_id/dest_type
    for entry in results:
        dest_id = entry.get("dest_id")
        dest_type = entry.get("dest_type")
        if dest_id and dest_type:
            return (dest_id, dest_type)
    return (None, None)


def search_hotels(dest_id: str, dest_type: str):
    """
    Search hotels for the given destination.
    Returns a list of hotel IDs (int). Returns empty list on failure.
    """
    if not dest_id or not dest_type:
        return []

    try:
        response = Search_hotels(
            checkin_date=CHECKIN_DATE,
            checkout_date=CHECKOUT_DATE,
            dest_type=dest_type,
            dest_id=dest_id,
            order_by=ORDER_BY,
            room_number=ROOM_NUMBER,
            filter_by_currency=FILTER_BY_CURRENCY
        )
    except Exception:
        return []

    # Extract result array from response
    result = response.get("result", [])
    if not result:
        return []

    hotel_ids = []
    for hotel in result:
        hid = hotel.get("hotel_id")
        if hid is not None:
            hotel_ids.append(int(hid))
    return hotel_ids


def get_hotel_policies(hotel_id: int):
    """
    Retrieve policy information for a hotel.
    Returns the raw JSON as returned by the API, or None on failure.
    """
    try:
        return Get_Policies_of_the_hotel(hotel_id)
    except Exception:
        return None


def is_flexible(policy_data: dict) -> bool:
    """
    Determine if the cancellation policy is flexible.
    Leniently checks policy text for keywords like 'free cancellation' or 'flexible'.
    """
    if not policy_data:
        return False

    # Navigate to the 'policy' array
    policies = policy_data.get("policy", [])
    for pol in policies:
        # Look for a cancellation‐related policy type
        pol_type = pol.get("type", "")
        if "cancel" in pol_type.lower():
            # Examine content for English text
            content_list = pol.get("content", [])
            for content in content_list:
                lang = content.get("languagecode", "")
                if lang == "en":
                    # Check ruleset text
                    ruleset = content.get("ruleset", [])
                    for rule_group in ruleset:
                        rules = rule_group.get("rule", [])
                        for rule in rules:
                            rule_text = rule.get("content", "")
                            if "free cancellation" in rule_text.lower() or "flexible" in rule_text.lower():
                                return True
                    # Also check other text fields
                    for field in ("name", "text"):
                        val = content.get(field, "")
                        if isinstance(val, str):
                            if "free cancellation" in val.lower() or "flexible" in val.lower():
                                return True
    return False


def compute_proportion():
    """
    Main logic: search location, get hotels, check policies, compute proportion.
    Returns a float between 0 and 1, or None if no data.
    """
    dest_id, dest_type = search_location(LOCATION_NAME)
    if dest_id is None:
        return None

    hotel_ids = search_hotels(dest_id, dest_type)
    if not hotel_ids:
        return None

    total = len(hotel_ids)
    flexible_count = 0

    for hid in hotel_ids:
        policy = get_hotel_policies(hid)
        if is_flexible(policy):
            flexible_count += 1

    return flexible_count / total


def main():
    proportion = compute_proportion()
    if proportion is None:
        print(f"No hotels found for '{LOCATION_NAME}'.")
        return

    print(f"Proportion of hotels in {LOCATION_NAME} with a flexible cancellation policy: {proportion:.2%}")


if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Maps_Data.Search import Search

import traceback

# --- Constants ---
QUERY = "America Bar & Grill"

# --- Helper functions ---
def search_business(query):
    """Search for a business by name using the Search API."""
    return Search(query)

def extract_first_business(search_results):
    """Extract the first business object from search results."""
    data = search_results.get("data", [])
    if not data:
        raise ValueError("No businesses found in search results.")
    return data[0]

def get_state_from_business(business):
    """Extract the state field from a business object."""
    return business.get("state")

# --- Main orchestration ---
def main():
    results = search_business(QUERY)
    business = extract_first_business(results)
    state = get_state_from_business(business)
    print(f"America Bar & Grill is located in {state}.")

if __name__ == "__main__":
    try:
        main()
    except Exception:
        traceback.print_exc(file=sys.stderr)

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Local_Business_Data.Search import Search

import traceback

# Module-level constants derived directly from user requirement
QUERY = "T5L 2L4 Edmonton AB"


def search_businesses_by_postal_code() -> list:
    """
    Calls the Search API with a query containing the postal code,
    city and region. Returns the list of business entries.
    """
    try:
        response = Search(QUERY)
    except Exception as e:
        raise RuntimeError("API call failed") from e

    data = response.get("data")
    if data is None:
        raise ValueError("Response missing 'data' key")
    return data


def count_results(business_list: list) -> int:
    """Returns the number of businesses in the provided list."""
    return len(business_list)


def main() -> None:
    """Orchestrates the workflow and prints the total count."""
    try:
        businesses = search_businesses_by_postal_code()
        total = count_results(businesses)
        print(f"Number of businesses in {QUERY}: {total}")
    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

import sys
from pathlib import Path
PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from Tools.Local_Business_Data.Search import Search
from Tools.Local_Business_Data.Business_Details import Business_Details

import traceback

# ===== Module-level constants =====
SEARCH_QUERY = "Body Shops Brentwood"
REGION = "us"
# =================================

def search_body_shops():
    """Search for body shops in Brentwood and return a list of business IDs."""
    response = Search(SEARCH_QUERY)
    data = response.get("data", [])
    business_ids = []
    for biz in data:
        bid = biz.get("business_id")
        if bid:
            business_ids.append(bid)
    return business_ids

def get_business_rating(business_id):
    """Retrieve the star rating for a business using Business_Details."""
    details = Business_Details(business_id, REGION)
    data = details.get("data", [])
    if not data:
        return None
    return data[0].get("rating")

def compute_average_ratings(ratings):
    """Compute the average of a list of ratings."""
    if not ratings:
        return 0.0
    return sum(ratings) / len(ratings)

def main():
    try:
        business_ids = search_body_shops()
        if not business_ids:
            print("No Body Shops businesses found in Brentwood.")
            return

        ratings = []
        for bid in business_ids:
            rating = get_business_rating(bid)
            if rating is not None:
                ratings.append(rating)

        if not ratings:
            print("No ratings could be retrieved for any Body Shops businesses.")
            return

        avg_rating = compute_average_ratings(ratings)
        print(f"Average star rating of Body Shops businesses in Brentwood: {avg_rating:.2f}")

    except Exception:
        traceback.print_exc(file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
